305	    /** Void a settled claim: only a steward may, within {@value #VOID_SETTLED_DAYS} days of its
306	     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
307	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
308	    private Claim voidSettled(String sheetId, String user, Claim claim, String voidReason) {
309	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
310	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
311	        }
312	        LocalDate today = sheets.today(sheetId);
313	        LocalDate settled = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
314	                .map(ClaimLog::getOn).findFirst().orElse(null);
315	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT,
317	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
318	        }
319	        return rollup.tracking(sheetId, user, () -> {
320	            Person person = person(sheetId, claim.getPersonId());
321	            BigDecimal reversed = dues.figure(sheetId, person, claim);
322	            claim.setStatus(ClaimStatus.VOID);
323	            claim.setVoidReason(voidReason);
324	            logStatus(sheetId, user, person, claim);
325	            Claim saved = claims.saveAndFlush(claim);
326	            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed)
327	                    + reasonText(voidReason));
328	            return saved;
329	        });
330	    }
