463	    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
464	     *  statement if that statement included it. Refused unless the claim is pending, the user is a
465	     *  steward, and the claim's period is open. */
466	    @Transactional
467	    public Claim reject(String sheetId, String user, long claimId, String reason) {
468	        Claim claim = lockPending(sheetId, user, claimId);
469	        return rollup.tracking(sheetId, user, () -> {
470	            Person person = person(sheetId, claim.getPersonId());
471	            claim.setStatus(ClaimStatus.OPEN);
472	            // back to open, it is no longer settled by the batch that left it pending
473	            claim.setSettleBatch(null);
474	            logStatus(sheetId, user, person, claim);
475	            Claim saved = claims.saveAndFlush(claim);
476	            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
477	            return saved;
478	        });
479	    }
480	
481	    /** Move a draft, open or pending claim to another person on the sheet. It keeps its date and
482	     *  status, takes the next number (a draft, having none, gets none), loses any figure a statement bound it to, and is listed as its new person's newest
483	     *  claim. Refused unless the permission matrix allows the user's role to reassign, and when the claim is settled or void, the person
484	     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
485	     *  new person's retirement day. */
486	    @Transactional
487	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
488	        return reassign(sheetId, user, claimId, toPersonId, false);
489	    }
490	
491	    /** Move a claim as {@link #reassign(String, String, long, long)} does; a bulk move ({@code
492	     *  inBulk}) also takes a claim that is already the person's, listing it as their newest. */
493	    @Transactional
494	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId, boolean inBulk) {
495	        Claim claim = lock(sheetId, claimId);
496	        if (!roles.may(sheetId, user, "reassign")) {
497	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
498	        }
499	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
500	            throw new ResponseStatusException(HttpStatus.CONFLICT,
501	                    "A " + claim.getStatus() + " claim cannot be reassigned");
502	        }
503	        if (!inBulk && claim.getPersonId() == toPersonId) {
504	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
505	        }
506	        refuseClosed(sheetId, claim.getDueBy());
507	        Person from = person(sheetId, claim.getPersonId());
508	        Person to = person(sheetId, toPersonId);
509	        refuseRetired(to, claim.getDate());
510	        return rollup.tracking(sheetId, user, () -> {
511	            claim.moveTo(to.getId(), claims.nextListed());
512	            if (claim.getNumber() != null) {
513	                // a moved claim takes the next number; its old one is never used again
514	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
515	            }
516	            Claim saved = claims.saveAndFlush(claim);
517	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
518	                    + " from=" + from.getName() + " to=" + to.getName());
519	            return saved;
520	        });
521	    }
522	
523	    /** Re-date an open or pending claim: it keeps the due-by it was fixed with, and so its period and
524	     *  number, and any figure a statement bound it to. Refused unless the user is a steward, and when
525	     *  the claim is not open or pending, its period is closed, or the new date is after the person's
526	     *  retirement day. */
527	    @Transactional
528	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
529	        Claim claim = lock(sheetId, claimId);
530	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
531	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim");
532	        }
533	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
534	            throw new ResponseStatusException(HttpStatus.CONFLICT,
535	                    "A " + claim.getStatus() + " claim cannot be re-dated");
536	        }
537	        refuseClosed(sheetId, claim.getDueBy());
538	        refuseRetired(person(sheetId, claim.getPersonId()), date);
539	        LocalDate old = claim.getDate();
540	        return rollup.tracking(sheetId, user, () -> {
541	            Person person = person(sheetId, claim.getPersonId());
542	            claim.setDate(date);
543	            Claim saved = claims.saveAndFlush(claim);
544	            audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
545	                    + " old=" + old + " new=" + date);
546	            return saved;
547	        });
548	    }
549	
550	    /** What a split leaves:the original claim, with the rest of its amount, and the new open claim
551	     *  split off it. */
552	    public record Split(Claim original, Claim split) {
553	    }
554	
555	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
556	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
557	     *  the same date and note, the next number, opened by the user and due by the terms in force on
558	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
559	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
560	     *  allow the user's role to open a claim. */
561	    @Transactional
562	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
563	        Claim claim = lock(sheetId, claimId);
564	        refuseClosed(sheetId, claim.getDueBy());
565	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
566	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
567	        }
568	        if (!roles.may(sheetId, user, "open")) {
569	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
570	        }
571	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
572	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
573	                    "The amount split off must be above 0.00 and below the claim's amount");
574	        }
575	        return rollup.tracking(sheetId, user, () -> {
576	            Person person = person(sheetId, claim.getPersonId());
577	            int terms = terms(sheetId, person, claim.getDate());
578	            LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
579	            Claim draft = claim.splitOff(part, nextNumber(sheetId, dueBy), user, dueBy, terms);
580	            logStatus(sheetId, user, person, draft);
581	            Claim original = claims.saveAndFlush(claim);
582	            Claim split = claims.saveAndFlush(draft);
583	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
584	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
585	            return new Split(original, split);
586	        });
587	    }
