589	    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
590	     *  user is not a steward, or its period is closed. */
591	    private Claim lockPending(String sheetId, String user, long claimId) {
592	        Claim claim = lock(sheetId, claimId);
593	        refuseClosed(sheetId, claim.getDueBy());
594	        if (claim.getStatus() != ClaimStatus.PENDING) {
595	            throw new ResponseStatusException(HttpStatus.CONFLICT,
596	                    "Only a PENDING claim can be approved or rejected");
597	        }
598	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
599	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
600	                    "Only a steward can approve or reject a claim");
601	        }
602	        return claim;
603	    }
604	
605	    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
606	     *  computed at this moment. */
607	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
608	        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
609	    }
610	
611	    private Claim lock(String sheetId, long claimId) {
612	        return claims.lockByIdAndSheetId(claimId, sheetId)
613	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
614	    }
615	
616	    private static String dueText(BigDecimal due) {
617	        return due == null ? "n/a" : due.setScale(2).toPlainString();
618	    }
619	
620	    /** The number for a claim due by the day opened now: under period numbering, the next in its period
621	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
622	    public String nextNumber(String sheetId, LocalDate dueBy) {
623	        if (!sheets.periodNumbering(sheetId)) {
624	            return String.valueOf(sheets.nextClaimNumber(sheetId));
625	        }
626	        return periods.findOn(sheetId, dueBy)
627	                .map(p -> {
628	                    periods.advanceClaimNumber(p.getId());
629	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
630	                })
631	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
632	    }
633	
634	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
635	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
636	     *  or else it is refused. */
637	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
638	        if (amount.signum() >= 0) {
639	            return null;
640	        }
641	        return (corrects == null ? Optional.<Claim>empty()
642	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
643	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
644	                        "A negative amount must correct a settled claim of the same person"));
645	    }
646	
647	    /** Refuse a change to a claim due by the day when the day falls inside a closed period. */
648	    private void refuseClosed(String sheetId, LocalDate day) {
649	        if (periods.closedOn(sheetId, day)) {
650	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
651	        }
652	    }
653	
654	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
655	     *  no due (n/a) is within any limit, and a steward settles anything. */
656	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
657	        BigDecimal limit = sheets.clerkLimit(sheetId);
658	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
659	            return false;
660	        }
661	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
662	        return due != null && due.compareTo(limit) > 0;
663	    }
664	
665	    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in
666	     *  force on the claim's date: its person's grade's (on that date) when one is set, or else the
667	     *  sheet's; a claim with no due (n/a) and a claim with no threshold need none. */
668	    private void refuseUnproved(String sheetId, Claim claim) {
669	        if (claim.getProofs() > 0) {
670	            return;
671	        }
672	        Person person = person(sheetId, claim.getPersonId());
673	        BigDecimal threshold = sheets.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
674	        if (threshold == null) {
675	            return;
676	        }
677	        BigDecimal due = dues.figure(sheetId, person, claim);
678	        if (due != null && due.compareTo(threshold) > 0) {
679	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
680	                    "A claim whose due is above the proof threshold needs a proof first");
681	        }
682	    }
683	
684	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
685	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
686	    private void refuseUnnoted(String sheetId, Claim claim) {
687	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
688	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
689	            return;
690	        }
691	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
692	        if (due != null && due.compareTo(threshold) > 0) {
693	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
694	                    "A claim whose due is above the note threshold needs a note before it is opened");
695	        }
696	    }
697	
698	    /** Refuse a claim of the person dated after the day they are retired from. */
699	    private static void refuseRetired(Person person, LocalDate day) {
700	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
701	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
702	                    "A claim cannot be dated after the person's retirement");
703	        }
704	    }
705	
706	    /** The terms a claim of the person dated on the day has its due-by fixed with (the terms-th
707	     *  business day after its date, skipping every Saturday, Sunday and holiday of the sheet): the
708	     *  first of the person's own terms, their grade's and the sheet's, each as in force on the day. */
709	    private int terms(String sheetId, Person person, LocalDate on) {
710	        Integer own = person.getTerms();
711	        return own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on);
712	    }
713	
714	    /** Refuse a reference (null: none) another claim of the sheet than the one given (null: any) has,
715	     *  comparing without regard to case. */
716	    /** The tags ever used on the sheet, in order. */
717	    @Transactional(readOnly = true)
718	    public List<String> tags(String sheetId) {
719	        return sheetTags.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
720	    }
721	
722	    /** Keep each of the tags (as {@link Tags} stores them) as used on the sheet. */
723	    public void keepTags(String sheetId, String tags) {
724	        for (String tag : Tags.of(tags)) {
725	            if (!sheetTags.existsBySheetIdAndTag(sheetId, tag)) {
726	                sheetTags.save(new SheetTag(sheetId, tag));
727	            }
728	        }
729	    }
730	
731	    public void refuseRefUsed(String sheetId, String ref, Long exceptId) {
732	        if (ref != null && claims.refUsed(sheetId, ref, exceptId)) {
733	            throw new ResponseStatusException(HttpStatus.CONFLICT,
734	                    "The reference \"" + ref + "\" is already used on this sheet");
735	        }
736	    }
737	
738	    private Person person(String sheetId, long personId) {
739	        return people.findByIdAndSheetId(personId, sheetId)
740	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
741	    }
742	
743	    /** An audit record about a claim; one that has a number carries it at the end. */
744	    /** The end of a void's record: its reason, when one was given. */
745	    private static String reasonText(String voidReason) {
746	        return voidReason == null ? "" : " reason=" + voidReason;
747	    }
748	
749	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
750	        String number = claim.getNumber();
751	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
752	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
753	                + (number != null ? " number=" + number : "");
754	    }
